<?php if(!empty($result['insights'])):?><section class="panel report-section"><div class="panel-head"><h3 class="panel-title">Important findings</h3></div><div class="panel-body"><ul class="mb-0"><?php foreach($result['insights'] as $item):?><li class="mb-2"><?=e(is_array($item)?($item['text']??json_encode($item)):$item)?></li><?php endforeach;?></ul></div></section><?php endif;?>
