<?php if(!empty($result['table'])):?><section class="panel report-section"><div class="panel-head"><h3 class="panel-title">Calculated data</h3></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Group / period</th><th>Calculated value</th><th>Rows</th></tr></thead><tbody><?php foreach(array_slice($result['table'],0,100) as $row):?><tr><td><?=e($row['label']??'—')?></td><td><?=e(!empty($row['currency'])?format_money((float)($row['value']??0),$row['currency']):format_number((float)($row['value']??0),2))?></td><td><?=e(isset($row['rows'])?format_number((int)$row['rows']):'—')?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
